    stroke-dasharray: 100;
}

.format-cards .course-content .card-deck .card .card-header-fade .section-completion svg circle.inner.complete {
    stroke-dasharray: 0;
}

.format-cards .empty-placeholder-image-lg {
    height: 5rem;
}

.format-cards .single-section .course-section {
    border: none;
}

.format-cards .course-content .single-section .section-navigation {
    margin-bottom: unset;
}

.format-cards .course-content .card-deck .card .card-img-top {
    transition: 0.4s filter ease-in-out;
}

.format-cards .course-content .card-deck .card:hover .card-img-top,
.format-cards .course-content .card-deck .card .card-main-content:focus-visible .card-img-top {
    filter: brightness(110%);
}
.format-cards .course-content .card-deck .card.hiddenfromstudents .card-img-top {
    filter: blur(1px) grayscale(80%);
}
.format-cards .course-content .card-deck .card.hiddenfromstudents:hover .card-img-top,
.format-cards .course-content .card-deck .card.hiddenfromstudents .card-main-content:focus-visible .card-img-top {
    filter: grayscale(75%);
}

.format-cards .course-content .card-deck .section.course-section {
    width: 100%;
}

.format-cards .course-content .card-deck .section-break {
    list-style: none;
    display: block;
    width: 100%;
}

@media (max-width: 576px) {

    .format-cards .course-content .card-deck .card .card-header .card-title {
        /** Try to make card titles responsive on smaller devices */
        font-size: min(3rem, 16vw);
    }
}

.format-cards .course-content .section-item .activity:first-of-type {
    border: none;
}

