    border-color: #354063;
    color: #e8eaf0;
}

body.format-simple[data-simple-theme="dark"][data-simple-theme="dark"] .tox .tox-button--naked {
    color: #e8eaf0;
}

body.format-simple[data-simple-theme="dark"][data-simple-theme="dark"] :is(
.tox .tox-button--naked:hover:not(:disabled),
.tox .tox-button--naked:focus:not(:disabled)) {
