}
.format-topicsactivitycards.path-course-view #page ul.topicsactivitycards li.section.tac-container .activity:not(.tac-container) {
  padding: 0.5em;
}
.format-topicsactivitycards.path-course-view #page ul.topicsactivitycards li.section.tac-container .activity:not(.tac-container) .activity-item {
  padding: 0;
}
.format-topicsactivitycards.path-course-view #page ul.topicsactivitycards li.section.tac-container .activity:not(.tac-container):not(:last-child) .activity-item {
  border: 0;
