  border-bottom: 1px solid #dee2e6;
  padding-bottom: 15px;
}
.format-topicsactivitycards.path-course-view #page ul.topicsactivitycards li.section.tac-container .activity:not(.tac-container):last-child .activity-item {
  border: 0;
}
.format-topicsactivitycards.path-course-view #page ul.topicsactivitycards li.section.tac-container .activity {
  border: 0;
  padding: 0;
}
.format-topicsactivitycards.path-course-view #page ul.topicsactivitycards li.section.tac-container .section-inner-wrapper {
  border-radius: 0.5rem;
  border: 1px solid #dee2e6;
}
.format-topicsactivitycards.path-course-view #page ul.topicsactivitycards li.section.sectionheadinglinkedcard .icons-collapse-expand {
