}
.format-topicsactivitycards.path-course-view #page ul.topicsactivitycards li.section.layoutcards .activity-grid .align-self-start.flex-md-row {
  flex-direction: column !important;
}
.format-topicsactivitycards.path-course-view #page ul.topicsactivitycards li.section.layoutcards .activity-inner-wrapper {
  border-radius: 0.5rem;
  border: 1px solid #dee2e6;
  padding: 0 !important;
}
.format-topicsactivitycards.path-course-view #page ul.topicsactivitycards li.section.layoutcards .content ul.section {
  display: flex !important;
  flex-wrap: wrap;
}
.format-topicsactivitycards.path-course-view #page ul.topicsactivitycards .tac-card-img {
