}

@media (max-width: 767px) {
    #page-admin-report-eventlist-index dt {
        width: 100%;
        text-align: left;
    }

    #page-admin-report-eventlist-index dd {
        margin-left: 0;
    }

    #page-admin-report-eventlist-index dd + dd {
