}

.gradingform_rubric .criterion .levels .level.last {
    border-right: 1px solid #ddd;
}

.gradingform_rubric .plainvalue.empty {
    font-style: italic;
    color: #555;
}

/* Make invisible the buttons 'Move up' for the first criterion and
   'Move down' for the last, because those buttons will make no change */
.gradingform_rubric.editor .criterion.first .controls .moveup input,
.gradingform_rubric.editor .criterion.last .controls .movedown input {
    display: none;
}

/* replace buttons with images */
.gradingform_rubric.editor .delete input,
.gradingform_rubric.editor .duplicate input,
.gradingform_rubric.editor .moveup input,
.gradingform_rubric.editor .movedown input {
    background: none 2px 4px / 16px 16px no-repeat;
    text-indent: -1000em;
    cursor: pointer;
    border: none;
}

.gradingform_rubric.editor .criterion .controls .delete input {
    width: 24px;
    height: 24px;
    background-image: url(/theme/image.php/adaptable/core/1791909815/t/delete);
    margin: .3em .3em 0 .3em;
}

.gradingform_rubric.editor .criterion .controls .duplicate input {
    width: 24px;
    height: 24px;
    background-image: url(/theme/image.php/adaptable/core/1791909815/t/copy);
    margin: .3em .3em 0 .3em;
}

.gradingform_rubric.editor .levels .level .delete input {
    width: 24px;
    height: 24px;
    background-image: url(/theme/image.php/adaptable/core/1791909815/t/delete);
}

.gradingform_rubric.editor .moveup input {
    width: 24px;
    height: 24px;
    background-image: url(/theme/image.php/adaptable/core/1791909815/t/up);
    margin: .3em .3em 0 .3em;
}

.gradingform_rubric.editor .movedown input {
    width: 24px;
    height: 24px;
    background-image: url(/theme/image.php/adaptable/core/1791909815/t/down);
    margin: .3em .3em 0 .3em;
}

.gradingform_rubric.editor .addcriterion input,
.gradingform_rubric.editor .addlevel input {
    background: #fff url(/theme/image.php/adaptable/core/1791909815/t/add) 4px 6px / 16px 16px no-repeat;
    height: 30px;
    line-height: 1rem;
    padding-left: 24px;
