}

.tiny-aiplacement-fa-image {
    height: 100%;
    width: 100%;
    background-image: url(/theme/image.php/adaptable/tiny_aiplacement/1791909815/sparkles-image);
    background-repeat: no-repeat;
    background-position: center;
    background-color: rgba(255, 255, 255, 0.5);
    background-blend-mode: lighten;
    background-size: 100px 100px;
}

.tiny-aiplacement-toggle-container {
    position: relative;
    width: 100%;
    display: flex;
    justify-content: center;
    align-items: center;
}
.tiny-aiplacement-toggle-switch {
    display: none;
}
.tiny-aiplacement-toggle-slider {
    width: 100%;
    display: flex;
    justify-content: space-between;
    align-items: center;
    background-color: #fff;
    border-radius: 34px;
    padding: 2px;
    border: 1px solid #aaa;
}
.tiny-aiplacement-toggle-slider span {
    width: 50%;
    text-align: center;
    padding: 5px 0;
    border-radius: 34px;
    cursor: pointer;
    transition: background-color 0.3s, color 0.3s;
}
.tiny-aiplacement-toggle-switch:checked + .tiny-aiplacement-toggle-slider .tiny-aiplacement-slider-right {
    background-color: #007bff;
    color: white;
}
.tiny-aiplacement-toggle-switch:not(:checked) + .tiny-aiplacement-toggle-slider .tiny-aiplacement-slider-left {
    background-color: #007bff;
    color: white;
}

.tiny-aiplacement-aspect-ratio-container {
    display: flex;
}
.tiny-aiplacement-aspect-ratio-btn {
    position: relative;
    width: 100px;
    height: 75px;
    background-color: #f8f9fa;
    border-radius: 15px;
    text-align: center;
    cursor: pointer;
    display: flex;
    flex-direction: column;
    justify-content: center;
    align-items: center;
    transition: background-color 0.3s, border-color 0.3s;
}
